1	"use server";
2	
3	/**
4	 * Per-website management for a shared-hosting account.
5	 *
6	 * The account is the unit of billing and of every limit; a WEBSITE is the unit
7	 * the customer works in. Everything here is scoped to one website inside one
8	 * account, plus the two account-level things the redesigned panel needed and the
9	 * platform did not have: extra SFTP logins that can be confined to one site's
10	 * folder, and a picture of what a site actually looks like.
11	 *
12	 * Guard discipline is copied from lib/actions-hosting.ts and must stay copied:
13	 * `requireUser()` for identity, owner-or-admin on every row, `assertNotImpersonating()`
14	 * on anything that mints a credential or spends money, and a Serializable
15	 * transaction wherever a plan cap is being counted against.
16	 */
17	
18	import { randomBytes } from "node:crypto";
19	import { revalidatePath } from "next/cache";
20	import { db } from "./db";
21	import { requireUser, assertNotImpersonating } from "./auth";
22	import { SANDBOX } from "./sandbox";
23	import { encryptSecret, decryptSecret } from "./crypto-box";
24	import { debitWallet, InsufficientBalanceError } from "./wallet";
25	import { isValidUnixUsername } from "./hosting";
26	import {
27	  extraDiskCentsAt,
28	  extraDiskProrateCents,
29	  effectiveDiskGB,
30	  isValidExtraDiskAddGB,
31	  maxAddableExtraDiskGB,
32	  normalizeExtraDiskGB,
33	  EXTRA_DISK_STEP_GB,
34	  EXTRA_DISK_MIN_GB,
35	} from "./extra-disk";
36	import { extraDiskPerGbCents } from "./disk-expand";
37	import { remainingMonths } from "./proration";
38	import {
39	  parseSiteKey,
40	  siteDirs,
41	  isValidFtpLabel,
42	  isValidFtpChroot,
43	  ftpUsernameFor,
44	  isValidFtpUsername,
45	  ftpScopeLabel,
46	  MAX_FTP_USERS,
47	  FTP_SCOPE_ACCOUNT,
48	  type SiteKind,
49	} from "./hosting-sites";
50	
51	type Fail = { error: string };
52	export type SiteResult = { ok?: boolean; error?: string };
53	
54	/* ── ownership ────────────────────────────────────────────────────────── */
55	
56	/**
57	 * Owner-or-admin on an account, optionally requiring it to be live.
58	 *
59	 * Same three refusals the hosting actions already use, in the same order, so a
60	 * customer gets the same wording here as everywhere else: not found → forbidden
61	 * → still provisioning.
62	 */
63	type OwnedAccount = {
64	  user: Awaited<ReturnType<typeof requireUser>>;
65	  a: {
66	    id: string; userId: string; status: string; username: string; primaryDomain: string;
67	    diskQuotaMB: number; extraDiskGB: number; expiresAt: Date | null; planId: string;
68	    plan: { diskGB: number; name: string };
69	  };
70	};
71	
72	// Annotated explicitly rather than inferred: an inferred union of
73	// `{user,a}` and `{error}` gains `error?: undefined` on the success arm, which
74	// makes `ctx.error` `string | undefined` after an `"error" in ctx` narrow and
75	// then fails to satisfy every `{ error: string }` return below.
76	async function ownedAccount(
77	  accountId: string,
78	  opts: { active?: boolean } = {},
79	): Promise<OwnedAccount | Fail> {
80	  const user = await requireUser();
81	  const a = await db.hostingAccount.findUnique({
82	    where: { id: accountId },
83	    select: {
84	      id: true, userId: true, status: true, username: true, primaryDomain: true,
85	      diskQuotaMB: true, extraDiskGB: true, expiresAt: true, planId: true,
86	      plan: { select: { diskGB: true, name: true } },
87	    },
88	  });
89	  if (!a) return { error: "Account not found." };
90	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
91	  if (opts.active && a.status !== "ACTIVE") return { error: "The account is still being set up." };
92	  return { user, a };
93	}
94	
95	/** Resolve a site key to the row it names, on THIS account. Null if it isn't one
96	 *  of this account's sites — which is the cross-tenant guard for every action
97	 *  below that takes a siteKey from the client. */
98	async function resolveSite(accountId: string, siteKey: string): Promise<
99	  { kind: SiteKind; id: string | null; hostname: string; container: string; docroot: string } | null
100	> {
101	  const parsed = parseSiteKey(siteKey);
102	  if (!parsed) return null;
103	  if (parsed.kind === "primary") {
104	    const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { primaryDomain: true } });
105	    if (!a) return null;
106	    const d = siteDirs({ kind: "primary" });
107	    return { kind: "primary", id: null, hostname: a.primaryDomain, ...d };
108	  }
109	  if (parsed.kind === "subdomain") {
110	    const s = await db.hostingSubdomain.findFirst({
111	      where: { id: parsed.id, accountId, status: { not: "DELETING" } },
112	      select: { id: true, label: true, fqdn: true },
113	    });
114	    if (!s) return null;
115	    const d = siteDirs({ kind: "subdomain", label: s.label });
116	    return { kind: "subdomain", id: s.id, hostname: s.fqdn, ...d };
117	  }
118	  const ad = await db.hostingAddonDomain.findFirst({
119	    where: { id: parsed.id, accountId, status: { not: "DELETING" } },
120	    select: { id: true, domain: true },
121	  });
122	  if (!ad) return null;
123	  const d = siteDirs({ kind: "addon", domain: ad.domain });
124	  return { kind: "addon", id: ad.id, hostname: ad.domain, ...d };
125	}
126	
127	/* ══ website thumbnails ═══════════════════════════════════════════════════ */
128	
129	export type SiteThumbView = {
130	  siteKey: string;
131	  /** The hostname the picture was taken/uploaded FOR. */
132	  hostname: string;
133	  source: "CAPTURE" | "UPLOAD";
134	  status: "PENDING" | "READY" | "FAILED";
135	  /** True when the site's hostname has changed since — the picture is of a name
136	   *  this site no longer answers on, so the UI must not present it as current. */
137	  stale: boolean;
138	  error: string | null;
139	  capturedAt: string | null;
140	  /** Where to fetch the bytes, or null when there are none yet. */
141	  url: string | null;
142	};
143	
144	/** Every stored picture on an account, keyed by site. Owner or admin. */
145	export async function listSiteThumbs(accountId: string): Promise<SiteThumbView[]> {
146	  const ctx = await ownedAccount(accountId);
147	  if ("error" in ctx) return [];
148	  const rows = await db.hostingSiteThumb.findMany({
149	    where: { accountId },
150	    select: {
151	      id: true, siteKey: true, hostname: true, source: true, status: true,
152	      error: true, capturedAt: true, updatedAt: true, sizeBytes: true,
153	    },
154	  });
155	  // Resolve each key's CURRENT hostname so a stale picture can be flagged rather
156	  // than shown as though it depicts the site as it is now.
157	  const current = new Map<string, string>();
158	  const [subs, addons] = await Promise.all([
159	    db.hostingSubdomain.findMany({ where: { accountId }, select: { id: true, fqdn: true } }),
160	    db.hostingAddonDomain.findMany({ where: { accountId }, select: { id: true, domain: true } }),
161	  ]);
162	  current.set("primary", ctx.a.primaryDomain);
163	  for (const s of subs) current.set(`subdomain:${s.id}`, s.fqdn);
164	  for (const d of addons) current.set(`addon:${d.id}`, d.domain);
165	
166	  return rows.map((r) => ({
167	    siteKey: r.siteKey,
168	    hostname: r.hostname,
169	    source: r.source as "CAPTURE" | "UPLOAD",
170	    status: r.status as "PENDING" | "READY" | "FAILED",
171	    stale: (current.get(r.siteKey) ?? r.hostname) !== r.hostname,
172	    error: r.error,
173	    capturedAt: r.capturedAt?.toISOString() ?? null,
174	    // Cache-bust on updatedAt so a re-capture replaces the picture immediately.
175	    url: r.status === "READY" && r.sizeBytes > 0
176	      ? `/api/hosting/thumb?id=${r.id}&v=${r.updatedAt.getTime()}`
177	      : null,
178	  }));
179	}
180	
181	/**
182	 * Queue a REAL screenshot of one site's homepage.
183	 *
184	 * The capture itself is a HostingTask (`CAPTURE_SITE_THUMB`) run by the worker
185	 * with headless Chromium against the site's public hostname — see
186	 * lib/hosting-thumb.ts. Nothing is drawn here; the row goes to PENDING and the
187	 * panel shows "capturing" until the worker writes bytes or an error.
188	 *
189	 * Refused for a site that isn't serving yet, because a capture of a domain that
190	 * does not resolve produces a picture of an error page, and an error page
191	 * presented as "your website" is worse than no picture.
192	 */
193	export async function captureSiteThumb(accountId: string, siteKey: string): Promise<SiteResult> {
194	  const ctx = await ownedAccount(accountId, { active: true });
195	  if ("error" in ctx) return { error: ctx.error };
196	  const site = await resolveSite(accountId, siteKey);
197	  if (!site) return { error: "That website isn’t part of this account." };
198	
199	  const existing = await db.hostingSiteThumb.findUnique({
200	    where: { accountId_siteKey: { accountId, siteKey } },
201	    select: { id: true, status: true },
202	  });
203	  if (existing?.status === "PENDING") return { error: "A capture is already running for this site." };
204	
205	  await db.hostingSiteThumb.upsert({
206	    where: { accountId_siteKey: { accountId, siteKey } },
207	    create: { accountId, siteKey, hostname: site.hostname, source: "CAPTURE", status: "PENDING" },
208	    update: { hostname: site.hostname, source: "CAPTURE", status: "PENDING", error: null },
209	  });
210	  await db.hostingTask.create({
211	    data: { accountId, kind: "CAPTURE_SITE_THUMB", payload: JSON.stringify({ siteKey, hostname: site.hostname }) },
212	  });
213	  revalidatePath(`/dashboard/hosting/${accountId}`);
214	  return { ok: true };
215	}
216	
217	/** Remove a site's stored picture entirely — back to the placeholder plate. */
218	export async function clearSiteThumb(accountId: string, siteKey: string): Promise<SiteResult> {
219	  const ctx = await ownedAccount(accountId);
220	  if ("error" in ctx) return { error: ctx.error };
221	  if (!parseSiteKey(siteKey)) return { error: "Unknown website." };
222	  await db.hostingSiteThumb.deleteMany({ where: { accountId, siteKey } });
223	  revalidatePath(`/dashboard/hosting/${accountId}`);
224	  return { ok: true };
225	}
226	
227	/* ══ scoped SFTP logins ═══════════════════════════════════════════════════ */
228	
229	export type FtpUserView = {
230	  id: string;
231	  username: string;
232	  label: string;
233	  scopeKey: string;
234	  chrootPath: string;
235	  /** Human sentence for the scope, e.g. "Domain · shop.example.com". */
236	  scopeLabel: string;
237	  readOnly: boolean;
238	  status: string;
239	  error: string | null;
240	  createdAt: string;
241	};
242	
243	/** The scopes a customer may choose for a new login on this account: the whole
244	 *  plan, or any one of its websites. Derived from the account's REAL sites, so a
245	 *  scope that does not exist can never be offered. */
246	export async function listFtpScopes(accountId: string): Promise<{ key: string; label: string; path: string }[]> {
247	  const ctx = await ownedAccount(accountId);
248	  if ("error" in ctx) return [];
249	  const [subs, addons] = await Promise.all([
250	    db.hostingSubdomain.findMany({ where: { accountId, status: { not: "DELETING" } }, select: { id: true, label: true, fqdn: true } }),
251	    db.hostingAddonDomain.findMany({ where: { accountId, status: { not: "DELETING" } }, select: { id: true, domain: true } }),
252	  ]);
253	  const out = [
254	    { key: FTP_SCOPE_ACCOUNT, label: "Whole account — every website", path: "" },
255	    { key: "primary", label: `${ctx.a.primaryDomain} (main website)`, path: siteDirs({ kind: "primary" }).docroot },
256	  ];
257	  for (const s of subs) out.push({ key: `subdomain:${s.id}`, label: s.fqdn, path: siteDirs({ kind: "subdomain", label: s.label }).container });
258	  for (const d of addons) out.push({ key: `addon:${d.id}`, label: d.domain, path: siteDirs({ kind: "addon", domain: d.domain }).container });
259	  return out;
260	}
261	
262	export async function listFtpUsers(accountId: string): Promise<FtpUserView[]> {
263	  const ctx = await ownedAccount(accountId);
264	  if ("error" in ctx) return [];
265	  const rows = await db.hostingFtpUser.findMany({ where: { accountId }, orderBy: { createdAt: "asc" } });
266	  return rows.map((r) => ({
267	    id: r.id,
268	    username: r.username,
269	    label: r.label,
270	    scopeKey: r.scopeKey,
271	    chrootPath: r.chrootPath,
272	    scopeLabel: ftpScopeLabel(r.chrootPath),
273	    readOnly: r.readOnly,
274	    status: r.status,
275	    error: r.error,
276	    createdAt: r.createdAt.toISOString(),
277	  }));
278	}
279	
280	/**
281	 * Mint an extra SFTP login confined to one folder.
282	 *
283	 * The confinement is a unix user plus an sshd `Match User … ChrootDirectory`
284	 * block written by the worker — the SAME mechanism that already confines the
285	 * account's own login, and validated with `sshd -t` before any reload. The panel
286	 * therefore never claims the scope is in force: the row is PENDING until the
287	 * node reports back, and the credentials list says so.
288	 *
289	 * The cap is counted inside a Serializable transaction for the same reason
290	 * createHostingDatabase counts inside one — two concurrent creates must not both
291	 * read a stale count.
292	 */
293	export async function createFtpUser(
294	  accountId: string,
295	  labelRaw: string,
296	  scopeKey: string,
297	  readOnly: boolean,
298	): Promise<{ ok?: boolean; error?: string; username?: string; password?: string }> {
299	  const ctx = await ownedAccount(accountId, { active: true });
300	  if ("error" in ctx) return { error: ctx.error };
301	  await assertNotImpersonating();
302	
303	  const label = String(labelRaw ?? "").trim().toLowerCase();
304	  if (!isValidFtpLabel(label)) {
305	    return { error: "Use 1–16 lowercase letters, numbers or hyphens for the login name." };
306	  }
307	  if (!isValidUnixUsername(ctx.a.username)) return { error: "This account isn’t ready for extra logins yet." };
308	
309	  // Resolve the scope to a real directory on THIS account. "account" is the home.
310	  let chrootPath = "";
311	  if (scopeKey !== FTP_SCOPE_ACCOUNT) {
312	    const site = await resolveSite(accountId, scopeKey);
313	    if (!site) return { error: "That website isn’t part of this account." };
314	    // The primary site's own container IS the account home, so scoping "primary"
315	    // to the home would silently be the whole plan. Confine it to public_html
316	    // instead — which is what the customer means by "just the main website".
317	    chrootPath = site.kind === "primary" ? site.docroot : site.container;
318	  }
319	  if (!isValidFtpChroot(chrootPath)) return { error: "That folder can’t be used for a scoped login." };
320	
321	  const username = ftpUsernameFor(ctx.a.username, label);
322	  // Validated with the SCOPED-login validator, not the account one — see
323	  // isValidFtpUsername for why they are two functions and not one.
324	  if (!isValidFtpUsername(username)) return { error: "That login name doesn’t make a valid system user." };
325	
326	  const password = randomBytes(18).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 24);
327	
328	  try {
329	    await db.$transaction(async (tx) => {
330	      const n = await tx.hostingFtpUser.count({ where: { accountId, status: { in: ["PENDING", "ACTIVE"] } } });
331	      if (n >= MAX_FTP_USERS) throw new Error("CAP");
332	      const row = await tx.hostingFtpUser.create({
333	        data: {
334	          accountId, username, label, scopeKey: scopeKey || FTP_SCOPE_ACCOUNT,
335	          chrootPath, readOnly: !!readOnly,
336	          passwordEnc: encryptSecret(password), status: "PENDING",
337	        },
338	      });
339	      await tx.hostingTask.create({
340	        data: { accountId, kind: "CREATE_FTP_USER", payload: JSON.stringify({ ftpUserId: row.id }) },
341	      });
342	    }, { isolationLevel: "Serializable" });
343	  } catch (e) {
344	    if ((e as Error)?.message === "CAP") {
345	      return { error: `You can have up to ${MAX_FTP_USERS} extra SFTP logins on one account.` };
346	    }
347	    if ((e as { code?: string })?.code === "P2002") {
348	      return { error: "A login with that name already exists — pick another." };
349	    }
350	    return { error: "Couldn’t create that login. Nothing was changed." };
351	  }
352	
353	  await db.auditLog.create({
354	    data: { userId: ctx.user.id, action: "hosting.ftp.create", detail: `${username} → ${chrootPath || "(account home)"}` },
355	  }).catch(() => {});
356	  revalidatePath(`/dashboard/hosting/${accountId}`);
357	  return { ok: true, username, password };
358	}
359	
360	/** Reveal a scoped login's password. Owner only; never while impersonating —
361	 *  same rule as the account's own SFTP credential. */
362	export async function revealFtpPassword(id: string): Promise<{ password?: string; error?: string }> {
363	  const user = await requireUser();
364	  await assertNotImpersonating();
365	  const row = await db.hostingFtpUser.findUnique({
366	    where: { id },
367	    select: { passwordEnc: true, account: { select: { userId: true } } },
368	  });
369	  if (!row) return { error: "Not found." };
370	  if (row.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
371	  const pw = decryptSecret(row.passwordEnc);
372	  if (!pw) return { error: "No password on record — reset it to set a new one." };
373	  return { password: pw };
374	}
375	
376	/** Rotate a scoped login's password. Returns the new one once, and queues the
377	 *  node-side `chpasswd` — the credential is not live until that task completes. */
378	export async function resetFtpPassword(id: string): Promise<{ password?: string; error?: string }> {
379	  const user = await requireUser();
380	  await assertNotImpersonating();
381	  const row = await db.hostingFtpUser.findUnique({
382	    where: { id },
383	    select: { id: true, accountId: true, username: true, account: { select: { userId: true, status: true } } },
384	  });
385	  if (!row) return { error: "Not found." };
386	  if (row.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
387	  if (row.account.status !== "ACTIVE") return { error: "The account is still being set up." };
388	
389	  const password = randomBytes(18).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 24);
390	  await db.hostingFtpUser.update({ where: { id }, data: { passwordEnc: encryptSecret(password), error: null } });
391	  await db.hostingTask.create({
392	    data: { accountId: row.accountId, kind: "RESET_FTP_PASSWORD", payload: JSON.stringify({ ftpUserId: row.id }) },
393	  });
394	  revalidatePath(`/dashboard/hosting/${row.accountId}`);
395	  return { password };
396	}
397	
398	/** Remove a scoped login: the row flips to DELETING and the worker drops the
399	 *  sshd block and the unix user. The row is deleted by the worker, not here, so
400	 *  the panel can show the removal in flight instead of pretending it is done. */
401	export async function deleteFtpUser(id: string): Promise<SiteResult> {
402	  const user = await requireUser();
403	  await assertNotImpersonating();
404	  const row = await db.hostingFtpUser.findUnique({
405	    where: { id },
406	    select: { id: true, accountId: true, username: true, account: { select: { userId: true } } },
407	  });
408	  if (!row) return { error: "Not found." };
409	  if (row.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
410	  await db.hostingFtpUser.update({ where: { id }, data: { status: "DELETING" } });
411	  await db.hostingTask.create({
412	    data: { accountId: row.accountId, kind: "DELETE_FTP_USER", payload: JSON.stringify({ ftpUserId: row.id }) },
413	  });
414	  await db.auditLog.create({
415	    data: { userId: user.id, action: "hosting.ftp.delete", detail: row.username },
416	  }).catch(() => {});
417	  revalidatePath(`/dashboard/hosting/${row.accountId}`);
418	  return { ok: true };
419	}
420	
421	/* ══ database ↔ website association ═══════════════════════════════════════ */
422	
423	/**
424	 * Record which website a database belongs to.
425	 *
426	 * A LABEL, not a boundary — see the note on HostingDatabase.siteKey. Every
427	 * database on the account is reachable from every site on it, because they share
428	 * one unix user and one account-scoped MySQL grant. This exists so the per-site
429	 * dashboard can show the customer which database that site's app uses, which is
430	 * the actual question they are asking.
431	 */
432	export async function setDatabaseSite(dbId: string, siteKey: string | null): Promise<SiteResult> {
433	  const user = await requireUser();
434	  const row = await db.hostingDatabase.findUnique({
435	    where: { id: dbId },
436	    select: { id: true, accountId: true, account: { select: { userId: true } } },
437	  });
438	  if (!row) return { error: "Not found." };
439	  if (row.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
440	  if (siteKey) {
441	    const site = await resolveSite(row.accountId, siteKey);
442	    if (!site) return { error: "That website isn’t part of this account." };
443	  }
444	  await db.hostingDatabase.update({ where: { id: dbId }, data: { siteKey: siteKey || null } });
445	  revalidatePath(`/dashboard/hosting/${row.accountId}`);
446	  return { ok: true };
447	}
448	
449	/* ══ storage add-on ═══════════════════════════════════════════════════════ */
450	
451	export type StorageQuote = {
452	  planDiskGB: number;
453	  extraDiskGB: number;
454	  effectiveGB: number;
455	  /** Largest single purchase still allowed under the effective-disk ceiling. */
456	  maxAddGB: number;
457	  stepGB: number;
458	  minGB: number;
459	  perGbCents: number;
460	  /** Whole months left on the paid term — what the one-off charge prorates over. */
461	  monthsRemaining: number;
462	  /** For the amount asked about: the monthly add and the charge due now. */
463	  addGB: number;
464	  monthlyCents: number;
465	  chargeNowCents: number;
466	  walletCents: number;
467	};
468	
469	/**
470	 * Price extra storage for a hosting account, using the SAME helpers the VPS
471	 * add-storage path uses (lib/extra-disk.ts + lib/proration.ts) so the figure a
472	 * customer is shown is the figure the charge is computed from. Nothing here
473	 * spends anything.
474	 */
475	export async function quoteHostingStorage(accountId: string, addGBRaw: number): Promise<StorageQuote | Fail> {
476	  const ctx = await ownedAccount(accountId);
477	  if ("error" in ctx) return { error: ctx.error };
478	  const planDiskGB = ctx.a.plan.diskGB;
479	  const extra = ctx.a.extraDiskGB ?? 0;
480	  const perGbCents = await extraDiskPerGbCents();
481	  const months = remainingMonths(ctx.a.expiresAt, Date.now());
482	  const addGB = normalizeExtraDiskGB(addGBRaw);
483	  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);
484	  return {
485	    planDiskGB,
486	    extraDiskGB: extra,
487	    effectiveGB: effectiveDiskGB(planDiskGB, extra),
488	    maxAddGB: maxAddableExtraDiskGB(planDiskGB, extra),
489	    stepGB: EXTRA_DISK_STEP_GB,
490	    minGB: EXTRA_DISK_MIN_GB,
491	    perGbCents,
492	    monthsRemaining: months,
493	    addGB,
494	    monthlyCents,
495	    chargeNowCents: extraDiskProrateCents(monthlyCents, months),
496	    walletCents: ctx.user.balanceCents,
497	  };
498	}
