1	/**
2	 * Shared vocabulary for "a website on a hosting account", and for the
3	 * folder-scoped SFTP logins that point at one.
4	 *
5	 * A shared-hosting plan is the unit of billing and of every limit. A WEBSITE is
6	 * the unit the customer actually works in, and a plan holds several: the primary
7	 * domain, plus each subdomain and each addon domain. Those three live in three
8	 * different tables, so everything that needs to name one uses a SITE KEY —
9	 * `"primary"`, `"subdomain:<id>"`, `"addon:<id>"` — which is exactly the `key`
10	 * `listWebsites()` already returns.
11	 *
12	 * This module is a plain (non-"use server") module on purpose: the worker daemon
13	 * imports the same path derivation the server actions validate against, so the
14	 * panel and the box can never disagree about which directory a scoped login was
15	 * confined to. Same discipline as lib/mod-install-support.ts.
16	 *
17	 * WHAT IS AND IS NOT ISOLATED, because the UI is required to be honest about it:
18	 *   • Files ARE separated per website — each site has its own docroot under the
19	 *     account home (`public_html`, `subdomains/<label>/public_html`,
20	 *     `domains/<domain>/public_html`), which is why a scoped SFTP login is
21	 *     meaningful at all.
22	 *   • Databases are NOT. Every database on the account is granted to the same
23	 *     account-level MySQL user and reachable from every site's PHP, because all
24	 *     the sites run in one FPM pool as one unix user. `HostingDatabase.siteKey`
25	 *     is a label the customer sets, and the panel calls it that.
26	 */
27	
28	/* ── site keys ────────────────────────────────────────────────────────── */
29	
30	export type SiteKind = "primary" | "subdomain" | "addon";
31	
32	export type ParsedSiteKey =
33	  | { kind: "primary"; id: null }
34	  | { kind: "subdomain"; id: string }
35	  | { kind: "addon"; id: string };
36	
37	const CUID_RE = /^[a-z0-9]{20,40}$/;
38	
39	/** Parse a site key, or null if it is not one. Never throws. */
40	export function parseSiteKey(key: string | null | undefined): ParsedSiteKey | null {
41	  const k = String(key ?? "").trim();
42	  if (k === "primary") return { kind: "primary", id: null };
43	  const m = /^(subdomain|addon):([a-z0-9]+)$/.exec(k);
44	  if (!m || !CUID_RE.test(m[2])) return null;
45	  return { kind: m[1] as "subdomain" | "addon", id: m[2] };
46	}
47	
48	export function isSiteKey(key: string | null | undefined): boolean {
49	  return parseSiteKey(key) !== null;
50	}
51	
52	export function siteKeyOf(kind: SiteKind, id: string | null): string {
53	  return kind === "primary" || !id ? "primary" : `${kind}:${id}`;
54	}
55	
56	/* ── the directories a site owns ──────────────────────────────────────── */
57	
58	/**
59	 * The two chroot-relative paths a website occupies inside the account home.
60	 *
61	 * `container` is the directory that HOLDS the site — for the primary site that
62	 * is the account home itself; for a subdomain/addon it is the per-site wrapper
63	 * the provisioner created. `docroot` is what nginx serves.
64	 *
65	 * The split matters for scoped SFTP: sshd refuses to chroot into a directory any
66	 * non-root user can write, and the docroot is deliberately writable by the
67	 * account (WordPress uploads). So a scoped login chroots to the CONTAINER and
68	 * the customer lands one level above their `public_html` — which is also what
69	 * they need, because that is where a site's non-public files live.
70	 */
71	export function siteDirs(site: { kind: SiteKind; label?: string | null; domain?: string | null }): {
72	  container: string;
73	  docroot: string;
74	} {
75	  if (site.kind === "subdomain") {
76	    const label = String(site.label ?? "");
77	    return { container: `subdomains/${label}`, docroot: `subdomains/${label}/public_html` };
78	  }
79	  if (site.kind === "addon") {
80	    const domain = String(site.domain ?? "");
81	    return { container: `domains/${domain}`, docroot: `domains/${domain}/public_html` };
82	  }
83	  // The primary site is served straight out of the account home.
84	  return { container: "", docroot: "public_html" };
85	}
86	
87	/* ── scoped SFTP logins ───────────────────────────────────────────────── */
88	
89	/** How many extra logins one account may hold. Each is a real unix user on a
90	 *  shared node, so this is a resource bound, not a UI preference. */
91	export const MAX_FTP_USERS = 8;
92	
93	/** "account" means the whole plan — every site, the account home as the chroot. */
94	export const FTP_SCOPE_ACCOUNT = "account";
95	
96	const FTP_LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,14}[a-z0-9])?$/;
97	
98	/**
99	 * A label for an extra login. Lowercase alnum with internal hyphens, ≤16 chars —
100	 * short because it becomes part of a unix username, and unix usernames are
101	 * length-bounded (32 on Linux) and must be shell-inert.
102	 */
103	export function isValidFtpLabel(label: string): boolean {
104	  return FTP_LABEL_RE.test(String(label ?? "").trim().toLowerCase());
105	}
106	
107	/**
108	 * The real unix username a label becomes: `<account>-<label>`, clipped to 32.
109	 *
110	 * A HYPHEN, not an underscore. Debian's default `NAME_REGEX` for adduser is
111	 * `^[a-z][-a-z0-9]*$` — an underscore is refused outright there, and shadow's
112	 * `useradd` only tolerates one with `--badname`. A hyphen is accepted by both and
113	 * is equally shell-inert. (Found the hard way: the first version generated
114	 * `acct_designer`, which `isValidUnixUsername` refused before it ever reached a
115	 * node, so no login could be created at all.)
116	 */
117	export function ftpUsernameFor(accountUsername: string, label: string): string {
118	  return `${accountUsername}-${label}`.slice(0, 32);
119	}
120	
121	/**
122	 * Validator for those derived names specifically.
123	 *
124	 * `isValidUnixUsername` (lib/hosting.ts) is deliberately stricter than Linux —
125	 * `^[a-z][a-z0-9]{2,31}$`, no separators at all — because it guards the ACCOUNT
126	 * username, which is interpolated into shell commands and filesystem paths all
127	 * over the provisioner. Loosening it to admit a scoped login's hyphen would widen
128	 * every one of those call sites at once, so this is a second, narrower validator
129	 * for exactly this one shape instead: an account name, one hyphen, a label.
130	 */
131	const FTP_USER_RE = /^[a-z][a-z0-9]{1,20}-[a-z0-9](?:[a-z0-9-]{0,13}[a-z0-9])?$/;
132	
133	export function isValidFtpUsername(name: string): boolean {
134	  const n = String(name ?? "");
135	  return n.length <= 32 && FTP_USER_RE.test(n);
136	}
137	
138	/**
139	 * Is a chroot path one this account may actually hand out?
140	 *
141	 * Deliberately a strict allow-list of shapes rather than a traversal filter: the
142	 * only directories a scoped login may be confined to are the account home and
143	 * the per-site containers the provisioner itself creates. Anything else — an
144	 * absolute path, a `..`, a path into `tmp`, an invented directory — is refused
145	 * here AND re-refused in the worker before it reaches a shell.
146	 */
147	export function isValidFtpChroot(path: string): boolean {
148	  const p = String(path ?? "");
149	  if (p === "") return true; // the account home
150	  if (p.startsWith("/") || p.includes("..") || p.includes("//")) return false;
151	  if (p === "public_html") return true;
152	  if (/^subdomains\/[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])?$/.test(p)) return true;
153	  if (/^domains\/[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?$/.test(p)) return true;
154	  return false;
155	}
156	
157	/** A human label for a chroot path, for the credentials list. */
158	export function ftpScopeLabel(chrootPath: string): string {
159	  if (!chrootPath) return "Whole account";
160	  if (chrootPath === "public_html") return "Main website files";
161	  const sub = /^subdomains\/(.+)$/.exec(chrootPath);
162	  if (sub) return `Subdomain · ${sub[1]}`;
163	  const dom = /^domains\/(.+)$/.exec(chrootPath);
164	  if (dom) return `Domain · ${dom[1]}`;
165	  return chrootPath;
166	}
