168	/* ── thumbnails ───────────────────────────────────────────────────────── */
169	
170	/** Capture size. 16:10 because that is the aspect the website cards draw at, and
171	 *  a capture that has to be re-cropped in CSS wastes half the bytes it stores. */
172	export const THUMB_WIDTH = 1280;
173	export const THUMB_HEIGHT = 800;
174	
175	/** Hard cap on a stored thumbnail, capture or upload. */
176	export const MAX_THUMB_BYTES = 4 * 1024 * 1024;
177	
178	export type ThumbSource = "CAPTURE" | "UPLOAD";
179	export type ThumbStatus = "PENDING" | "READY" | "FAILED";
