1	/**
2	 * Website preview capture — a REAL screenshot of a customer's own homepage.
3	 *
4	 * The hosting dashboard leads with a picture of the customer's website. There
5	 * are exactly three things that picture can be, and the panel always knows which:
6	 *
7	 *   1. a capture taken here — headless Chromium actually navigates to the site's
8	 *      public hostname and photographs what answers;
9	 *   2. an image the customer uploaded themselves;
10	 *   3. the product's own stock hosting plate, labelled as a placeholder.
11	 *
12	 * There is deliberately no fourth option. A stock photograph of *some* website
13	 * presented as *this* website is the exact shape this tree has already had to
14	 * delete once (hash-derived star ratings), so a capture that fails stores the
15	 * failure and the card falls back to the labelled plate.
16	 *
17	 * WHAT THIS WILL AND WILL NOT PHOTOGRAPH
18	 * - Only the hostname of a site on the account being captured, resolved from the
19	 *   database by the caller — never a URL from a request.
20	 * - Only over the public internet, from the panel host. It never reaches into a
21	 *   node, and it is not a way to make the panel fetch an arbitrary address: the
22	 *   hostname is validated here as well, and a resolved private/loopback address
23	 *   aborts the capture (SSRF guard — a customer can point their own domain's DNS
24	 *   at 127.0.0.1 and would otherwise have us photograph our own panel).
25	 *
26	 * Playwright is a devDependency used by this tree's own screenshot tooling, and
27	 * its Chromium is already installed on this box. It is `await import()`ed so a
28	 * host without it fails this one task with a legible error rather than failing to
29	 * boot; `next.config.ts` lists it under `serverExternalPackages` so the bundler
30	 * leaves its browser-path resolution alone.
31	 */
32	
33	import { lookup } from "node:dns/promises";
34	import { isValidHostingDomain } from "./hosting";
35	import { THUMB_WIDTH, THUMB_HEIGHT, MAX_THUMB_BYTES } from "./hosting-sites";
36	
37	/**
38	 * Chromium's navigation errors in the customer's own terms.
39	 *
40	 * The raw strings are engine internals — "page.goto: Navigation to
41	 * 'http://…' is interrupted by another navigation to…", "net::ERR_ABORTED" —
42	 * and the panel puts this text straight in front of the site's owner. Each
43	 * branch below maps a REAL condition to what it means for their website; the
44	 * fallback keeps the original first line rather than inventing a cause, so an
45	 * error we have not seen before still says something true.
46	 */
47	function friendlyNavError(raw: string): string {
48	  const m = raw.toLowerCase();
49	  if (m.includes("err_name_not_resolved") || m.includes("err_name_")) {
50	    return "The domain doesn’t resolve yet.";
51	  }
52	  if (m.includes("err_connection_refused")) return "Nothing is answering on that domain yet.";
53	  if (m.includes("err_connection_timed_out") || m.includes("timeout")) {
54	    return "The site didn’t respond in time.";
55	  }
56	  if (m.includes("err_too_many_redirects")) return "The site redirects in a loop, so there was nothing to photograph.";
57	  if (m.includes("err_cert") || m.includes("ssl")) return "The site’s certificate couldn’t be used.";
58	  if (m.includes("err_aborted") || m.includes("interrupted by another navigation")) {
59	    return "The site redirected somewhere we couldn’t follow.";
60	  }
61	  if (m.includes("err_empty_response")) return "The server closed the connection without sending a page.";
62	  return raw.split("\n")[0].slice(0, 160) || "The site didn’t answer.";
63	}
64	
65	export type CaptureResult =
66	  | { ok: true; bytes: Buffer; mime: string; width: number; height: number }
67	  | { ok: false; error: string };
68	
69	/** Total wall-clock budget for one capture. A site that cannot paint something
70	 *  in this long is a site whose picture would be a spinner. */
71	const NAV_TIMEOUT_MS = 20_000;
72	const SETTLE_MS = 1_200;
73	
74	function isPrivateAddress(ip: string): boolean {
75	  if (ip.includes(":")) {
76	    const v = ip.toLowerCase();
77	    // loopback, unspecified, link-local, unique-local
78	    return v === "::1" || v === "::" || v.startsWith("fe80") || v.startsWith("fc") || v.startsWith("fd");
79	  }
80	  const p = ip.split(".").map((n) => parseInt(n, 10));
81	  if (p.length !== 4 || p.some((n) => !Number.isFinite(n))) return true;
82	  const [a, b] = p;
83	  if (a === 10 || a === 127 || a === 0) return true;
84	  if (a === 172 && b >= 16 && b <= 31) return true;
85	  if (a === 192 && b === 168) return true;
86	  if (a === 169 && b === 254) return true;
87	  if (a === 100 && b >= 64 && b <= 127) return true; // CGNAT
88	  if (a >= 224) return true; // multicast / reserved
89	  return false;
90	}
91	
92	/**
93	 * Photograph a hostname's homepage.
94	 *
95	 * Returns bytes on success and a customer-readable reason on failure — the
96	 * reason is stored on the row and shown, because "we tried and the site did not
97	 * answer" is information the customer wants and "no preview" is not.
98	 */
99	export async function captureHomepage(hostname: string): Promise<CaptureResult> {
100	  const host = String(hostname ?? "").trim().toLowerCase();
101	  if (!isValidHostingDomain(host)) return { ok: false, error: "That isn’t a hostname we can reach." };
102	
103	  // Resolve first and refuse anything that points inside the network. A customer
104	  // controls their own DNS; without this they control what the panel fetches.
105	  try {
106	    const addrs = await lookup(host, { all: true });
107	    if (!addrs.length) return { ok: false, error: "The domain doesn’t resolve yet." };
108	    if (addrs.some((a) => isPrivateAddress(a.address))) {
109	      return { ok: false, error: "The domain resolves to a private address, so we can’t photograph it." };
110	    }
111	  } catch {
112	    return { ok: false, error: "The domain doesn’t resolve yet — point its DNS at us and try again." };
113	  }
114	
115	  let pw: typeof import("playwright");
116	  try {
117	    pw = await import("playwright");
118	  } catch {
119	    return { ok: false, error: "The preview service isn’t available on this host." };
120	  }
121	
122	  let browser: Awaited<ReturnType<typeof pw.chromium.launch>> | null = null;
123	  try {
124	    browser = await pw.chromium.launch({ args: ["--no-sandbox", "--disable-dev-shm-usage"] });
125	    const ctx = await browser.newContext({
126	      viewport: { width: THUMB_WIDTH, height: THUMB_HEIGHT },
127	      deviceScaleFactor: 1,
128	      ignoreHTTPSErrors: true, // a site mid-issuance still has a self-signed cert
129	      userAgent:
130	        "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0 Safari/537.36 NxeonPreview/1.0",
131	    });
132	    const page = await ctx.newPage();
133	    page.setDefaultTimeout(NAV_TIMEOUT_MS);
134	
135	    // HTTPS first; fall back to HTTP for a site whose certificate has not issued.
136	    let reached = false;
137	    let lastErr = "";
138	    for (const scheme of ["https", "http"]) {
139	      try {
140	        const res = await page.goto(`${scheme}://${host}/`, { waitUntil: "domcontentloaded", timeout: NAV_TIMEOUT_MS });
141	        if (res && res.status() >= 500) { lastErr = `The site answered ${res.status()}.`; continue; }
142	        reached = true;
143	        break;
144	      } catch (e) {
145	        lastErr = friendlyNavError((e as Error)?.message ?? "");
146	      }
147	    }
148	    if (!reached) return { ok: false, error: lastErr || "The site didn’t answer." };
149	
150	    // Give webfonts/hero images a moment — a screenshot taken at DOMContentLoaded
151	    // is usually an unstyled flash of the page, which looks like a broken site.
152	    await page.waitForTimeout(SETTLE_MS);
153	    await page.evaluate(() => window.scrollTo(0, 0)).catch(() => undefined);
154	
155	    const bytes = await page.screenshot({ type: "jpeg", quality: 76, fullPage: false });
156	    if (bytes.length > MAX_THUMB_BYTES) {
157	      return { ok: false, error: "The captured image came back too large to store." };
158	    }
159	    return { ok: true, bytes: Buffer.from(bytes), mime: "image/jpeg", width: THUMB_WIDTH, height: THUMB_HEIGHT };
160	  } catch (e) {
161	    return { ok: false, error: (e as Error)?.message?.split("\n")[0] ?? "The capture failed." };
162	  } finally {
163	    try { await browser?.close(); } catch { /* the process is going away regardless */ }
164	  }
165	}
