1	"use server";
2	
3	/**
4	 * Shared-hosting file-manager server actions.
5	 *
6	 * lib/actions-hosting.ts already had three of these (hostingListFiles,
7	 * hostingMkdir, hostingDeleteFile) — enough for a listing with a New folder and
8	 * a Delete button, not enough to drive the real file manager, which also reads,
9	 * saves and renames. This module is the COMPLETE set that lib/files-adapters.ts
10	 * `hostingFileApi` binds to, and it keeps the same ownership discipline as the
11	 * originals: owner-or-admin, ACTIVE account, and the chrooted-SFTP target built
12	 * by `fsTargetFor` (which connects AS the jailed account user — see the header of
13	 * lib/hosting-fs.ts for why that, and not root, is what makes this safe).
14	 *
15	 * Paths here are chroot-RELATIVE ("public_html/wp-config.php"), never absolute:
16	 * the adapter has already mapped the browser's virtual "/" onto the account's
17	 * base directory, and lib/hosting-fs's `safeRel` rejects traversal on every call
18	 * as defence in depth.
19	 */
20	
21	import { db } from "./db";
22	import { requireUser } from "./auth";
23	import { SANDBOX } from "./sandbox";
24	import type { FileEntry, FileMut } from "./files-types";
25	import {
26	  fsTargetFor,
27	  fsList,
28	  fsMkdir,
29	  fsDelete,
30	  fsRename,
31	  fsReadBuffer,
32	  fsWriteBuffer,
33	  fsStatSize,
34	  type FsEntry,
35	} from "./hosting-fs";
36	
37	/** Max size (bytes) for a text file opened/saved in the inline editor. Matches
38	 *  the VPS file manager's limit so the same editor behaves the same either side. */
39	const MAX_EDIT_BYTES = 1024 * 1024; // 1 MB
40	
41	const NOT_READY = "The file manager isn’t ready yet.";
42	/** Shown wherever SANDBOX means there is no filesystem behind this account at
43	 *  all. Deliberately says what it is rather than inventing a listing. */
44	const NO_NODE =
45	  "No hosting node is attached in this environment, so there are no files to read.";
46	
47	function loadAccount(id: string) {
48	  return db.hostingAccount.findUnique({ where: { id }, include: { node: true } });
49	}
50	type Account = NonNullable<Awaited<ReturnType<typeof loadAccount>>>;
51	
52	/**
53	 * Owner (or admin) + ACTIVE account, including the node — the same check the
54	 * three original file actions in lib/actions-hosting.ts do, replicated here
55	 * because that one is a local helper in a file this module must not import from
56	 * (a "use server" file may only export async functions).
57	 *
58	 * The `ok` discriminant is the only difference: the original returns a bare
59	 * `{ error }` vs `{ user, a }` union, which `"error" in ctx` does not narrow
60	 * cleanly under this tsconfig (the success branch survives the check with
61	 * `error: undefined`), so every call site would have to widen its own result.
62	 */
63	async function ownedAccountWithNode(
64	  id: string
65	): Promise<{ ok: false; error: string } | { ok: true; a: Account }> {
66	  const user = await requireUser();
67	  const a = await loadAccount(id);
68	  if (!a) return { ok: false, error: "Not found." };
69	  if (a.userId !== user.id && user.role !== "ADMIN") return { ok: false, error: "Forbidden." };
70	  if (a.status !== "ACTIVE") return { ok: false, error: "The account is still being set up." };
71	  return { ok: true, a };
72	}
73	
74	/** Octal permission string like "755" from the raw st_mode SFTP reported, or
75	 *  null when the server did not send one. Never a guessed default. */
76	function toMode(mode: number | null): string | null {
77	  return mode == null ? null : (mode & 0o777).toString(8).padStart(3, "0");
78	}
79	
80	function entryOut(e: FsEntry): FileEntry {
81	  return {
82	    name: e.name,
83	    isDirectory: e.isDir,
84	    size: e.size,
85	    modifiedMs: e.modified,
86	    mode: toMode(e.mode),
87	  };
88	}
89	
90	/** Trim a relative path to its parent, "" when it is already at the base. */
91	function parentRel(rel: string): string {
92	  const clean = rel.replace(/\/+$/, "");
93	  const cut = clean.lastIndexOf("/");
94	  return cut === -1 ? "" : clean.slice(0, cut);
95	}
96	
97	/** Same sanitiser hostingMkdir uses for a new folder name. */
98	function safeName(name: string): string {
99	  return String(name ?? "").trim().replace(/[^A-Za-z0-9._-]/g, "").slice(0, 120);
100	}
101	
102	// ---------------------------------------------------------------------------
103	
104	export async function hostingFsList(
105	  accountId: string,
106	  relPath: string
107	): Promise<{ ok: true; entries: FileEntry[] } | { ok: false; error: string }> {
108	  const ctx = await ownedAccountWithNode(accountId);
109	  if (!ctx.ok) return { ok: false, error: ctx.error };
110	  // No node, no filesystem: an EMPTY listing is the truthful answer, and the
111	  // browser renders its own "this folder is empty" state over it. Inventing a
112	  // plausible-looking tree here would be inventing customer data.
113	  if (SANDBOX) return { ok: true, entries: [] };
114	  const t = fsTargetFor(ctx.a);
115	  if (!t) return { ok: false, error: NOT_READY };
116	  try {
117	    const entries = await fsList(t, relPath);
118	    return { ok: true, entries: entries.map(entryOut) };
119	  } catch {
120	    return { ok: false, error: "Couldn’t read that folder." };
121	  }
122	}
123	
124	export async function hostingFsRead(
125	  accountId: string,
126	  relPath: string
127	): Promise<{ ok: true; content: string } | { ok: false; error: string }> {
128	  const ctx = await ownedAccountWithNode(accountId);
129	  if (!ctx.ok) return { ok: false, error: ctx.error };
130	  if (SANDBOX) return { ok: false, error: NO_NODE };
131	  const t = fsTargetFor(ctx.a);
132	  if (!t) return { ok: false, error: NOT_READY };
133	  try {
134	    // Stat first: fsReadBuffer concatenates the whole file into memory, so an
135	    // oversized file has to be refused BEFORE it is read, not after.
136	    const size = await fsStatSize(t, relPath);
137	    if (size > MAX_EDIT_BYTES) {
138	      return { ok: false, error: "File exceeds the 1 MB in-browser edit limit." };
139	    }
140	    const buf = await fsReadBuffer(t, relPath);
141	    return { ok: true, content: buf.toString("utf8") };
142	  } catch {
143	    return { ok: false, error: "Couldn’t open that file." };
144	  }
145	}
146	
147	export async function hostingFsSave(
148	  accountId: string,
149	  relPath: string,
150	  content: string
151	): Promise<FileMut> {
152	  const ctx = await ownedAccountWithNode(accountId);
153	  if (!ctx.ok) return { ok: false, error: ctx.error };
154	  if (typeof content !== "string") return { ok: false, error: "Invalid content." };
155	  if (Buffer.byteLength(content, "utf8") > MAX_EDIT_BYTES) {
156	    return { ok: false, error: "File exceeds the 1 MB in-browser edit limit." };
157	  }
158	  if (SANDBOX) return { ok: true };
159	  const t = fsTargetFor(ctx.a);
160	  if (!t) return { ok: false, error: NOT_READY };
161	  try {
162	    await fsWriteBuffer(t, relPath, Buffer.from(content, "utf8"));
163	    return { ok: true };
164	  } catch {
165	    return { ok: false, error: "Couldn’t save that file." };
166	  }
167	}
168	
169	export async function hostingFsMkdir(
170	  accountId: string,
171	  dirRelPath: string,
172	  name: string
173	): Promise<FileMut> {
174	  const ctx = await ownedAccountWithNode(accountId);
175	  if (!ctx.ok) return { ok: false, error: ctx.error };
176	  const clean = safeName(name);
177	  if (!clean) return { ok: false, error: "Enter a folder name." };
178	  if (SANDBOX) return { ok: true };
179	  const t = fsTargetFor(ctx.a);
180	  if (!t) return { ok: false, error: NOT_READY };
181	  const dir = String(dirRelPath ?? "").replace(/\/+$/, "");
182	  try {
183	    await fsMkdir(t, dir ? `${dir}/${clean}` : clean);
184	    return { ok: true };
185	  } catch {
186	    return { ok: false, error: "Couldn’t create the folder." };
187	  }
188	}
189	
190	export async function hostingFsRename(
191	  accountId: string,
192	  relPath: string,
193	  newName: string
194	): Promise<FileMut> {
195	  const ctx = await ownedAccountWithNode(accountId);
196	  if (!ctx.ok) return { ok: false, error: ctx.error };
197	  const clean = safeName(newName);
198	  if (!clean) return { ok: false, error: "Enter a name." };
199	  const from = String(relPath ?? "").replace(/\/+$/, "");
200	  if (!from || from === ".") return { ok: false, error: "The root directory cannot be renamed." };
201	  if (SANDBOX) return { ok: true };
202	  const t = fsTargetFor(ctx.a);
203	  if (!t) return { ok: false, error: NOT_READY };
204	  // Rename stays in the SAME parent directory — this backs a Rename control,
205	  // not a Move one (the VPS `renameEntry` behaves identically).
206	  const parent = parentRel(from);
207	  const to = parent ? `${parent}/${clean}` : clean;
208	  try {
209	    await fsRename(t, from, to);
210	    return { ok: true };
211	  } catch {
212	    return { ok: false, error: "Couldn’t rename it." };
213	  }
214	}
215	
216	export async function hostingFsDelete(
217	  accountId: string,
218	  relPath: string,
219	  isDirectory: boolean
220	): Promise<FileMut> {
221	  const ctx = await ownedAccountWithNode(accountId);
222	  if (!ctx.ok) return { ok: false, error: ctx.error };
223	  const clean = String(relPath ?? "").replace(/\/+$/, "");
224	  if (!clean || clean === ".") return { ok: false, error: "The root directory cannot be deleted." };
225	  if (SANDBOX) return { ok: true };
226	  const t = fsTargetFor(ctx.a);
227	  if (!t) return { ok: false, error: NOT_READY };
228	  try {
229	    await fsDelete(t, clean, isDirectory);
230	    return { ok: true };
231	  } catch {
232	    // fsDelete uses SFTP rmdir, which — unlike the VPS side's recursive
233	    // removePath — only removes an EMPTY directory. Say so rather than leaving
234	    // the customer to guess why a folder refused to go.
235	    return {
236	      ok: false,
237	      error: isDirectory
238	        ? "Couldn’t delete that folder. A folder has to be empty before it can be removed here."
239	        : "Couldn’t delete it.",
240	    };
241	  }
242	}
