1	import { NextRequest, NextResponse } from "next/server";
2	import { requireUser } from "@/lib/auth";
3	import { db } from "@/lib/db";
4	import { validateImageBytes } from "@/lib/chat-attachment";
5	import { parseSiteKey, MAX_THUMB_BYTES } from "@/lib/hosting-sites";
6	
7	/**
8	 * Website preview bytes.
9	 *
10	 * GET  — serve one stored preview (a capture or a customer upload). Owner or
11	 *        admin only: a preview is a photograph of the customer's site as it
12	 *        stands, which can include a staging page they have not published.
13	 * POST  — replace one site's preview with an image the customer supplies.
14	 * The bytes live on HostingSiteThumb in Postgres, the same convention
15	 * ChatAttachment and SignatureImage use.
16	 *
17	 * Upload validation goes through the platform's existing image validator, which
18	 * authenticates the bytes by SIGNATURE rather than the declared Content-Type and
19	 * refuses SVG outright. There is no second allow-list here for the two to drift
20	 * apart on.
21	 */
22	
23	/** Owner-or-admin on the account that owns a thumb row. */
24	async function ownedThumb(id: string) {
25	  const user = await requireUser();
26	  const row = await db.hostingSiteThumb.findUnique({
27	    where: { id },
28	    select: { id: true, mime: true, data: true, status: true, account: { select: { userId: true } } },
29	  });
30	  if (!row) return null;
31	  if (row.account.userId !== user.id && user.role !== "ADMIN") return null;
32	  return row;
33	}
34	
35	export async function GET(req: NextRequest) {
36	  const id = req.nextUrl.searchParams.get("id") ?? "";
37	  if (!id) return new NextResponse("Not found", { status: 404 });
38	  const row = await ownedThumb(id).catch(() => null);
39	  if (!row || row.status !== "READY" || !row.data || !row.mime) {
40	    return new NextResponse("Not found", { status: 404 });
41	  }
42	  return new NextResponse(new Uint8Array(row.data), {
43	    status: 200,
44	    headers: {
45	      "Content-Type": row.mime,
46	      // Private: this is the customer's own site, possibly unpublished. The URL
47	      // already carries an updatedAt cache-buster, so a long browser cache is
48	      // safe and a replacement is picked up immediately.
49	      "Cache-Control": "private, max-age=86400",
50	      "Content-Disposition": "inline",
51	    },
52	  });
53	}
54	
55	export async function POST(req: NextRequest) {
56	  const user = await requireUser().catch(() => null);
57	  if (!user) return NextResponse.json({ error: "Forbidden" }, { status: 403 });
58	
59	  const accountId = req.nextUrl.searchParams.get("accountId") ?? "";
60	  const siteKey = req.nextUrl.searchParams.get("siteKey") ?? "";
61	  if (!parseSiteKey(siteKey)) return NextResponse.json({ error: "Unknown website." }, { status: 400 });
62	
63	  const account = await db.hostingAccount.findUnique({
64	    where: { id: accountId },
65	    select: { id: true, userId: true, primaryDomain: true },
66	  });
67	  if (!account) return NextResponse.json({ error: "Not found" }, { status: 404 });
68	  if (account.userId !== user.id && user.role !== "ADMIN") {
69	    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
70	  }
71	
72	  // Resolve the site key to the hostname this picture is FOR, so a later rename
73	  // can be detected and the picture flagged stale rather than shown as current.
74	  const parsed = parseSiteKey(siteKey)!;
75	  let hostname = account.primaryDomain;
76	  if (parsed.kind === "subdomain") {
77	    const s = await db.hostingSubdomain.findFirst({ where: { id: parsed.id, accountId }, select: { fqdn: true } });
78	    if (!s) return NextResponse.json({ error: "That website isn’t part of this account." }, { status: 404 });
79	    hostname = s.fqdn;
80	  } else if (parsed.kind === "addon") {
81	    const d = await db.hostingAddonDomain.findFirst({ where: { id: parsed.id, accountId }, select: { domain: true } });
82	    if (!d) return NextResponse.json({ error: "That website isn’t part of this account." }, { status: 404 });
83	    hostname = d.domain;
84	  }
85	
86	  const form = await req.formData();
87	  const file = form.get("file");
88	  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });
89	  if (file.size > MAX_THUMB_BYTES) {
90	    return NextResponse.json({ error: "Image is larger than 4 MB." }, { status: 413 });
91	  }
92	
93	  const check = validateImageBytes(Buffer.from(await file.arrayBuffer()), file.type || null);
94	  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });
95	
96	  await db.hostingSiteThumb.upsert({
97	    where: { accountId_siteKey: { accountId, siteKey } },
98	    create: {
99	      accountId, siteKey, hostname, source: "UPLOAD", status: "READY",
100	      mime: check.mime, sizeBytes: check.bytes.length, data: new Uint8Array(check.bytes),
101	      error: null, capturedAt: new Date(),
102	    },
103	    update: {
104	      hostname, source: "UPLOAD", status: "READY",
105	      mime: check.mime, sizeBytes: check.bytes.length, data: new Uint8Array(check.bytes),
106	      error: null, capturedAt: new Date(), width: null, height: null,
107	    },
108	  });
109	
110	  return NextResponse.json({ ok: true });
111	}
