1	/**
2	 * Sandbox demo data for the shared-hosting panel.
3	 *
4	 * NODE-2 SANDBOX ONLY. It refuses to run unless NXEON_SANDBOX=1, because every
5	 * row it writes is a lie about a machine — an ACTIVE account with measured disk
6	 * usage on a node that does not exist. That is fine for looking at a design and
7	 * catastrophic anywhere else.
8	 *
9	 * Why it exists: the hosting panel's whole surface (websites, storage
10	 * breakdown, HTTPS state, databases, activity) is gated on
11	 * `status === "ACTIVE"`, and every seeded account on node-2 sits at PENDING
12	 * because nothing ever provisions them here. Without this there is nothing to
13	 * screenshot but an empty "still being set up" card.
14	 *
15	 *   NXEON_SANDBOX=1 npx tsx scripts/seed-hosting-demo.ts
16	 */
17	import { PrismaClient } from "@prisma/client";
18	import { encryptSecret } from "../lib/crypto-box";
19	
20	const db = new PrismaClient();
21	
22	async function main() {
23	  if (process.env.NXEON_SANDBOX !== "1") {
24	    throw new Error("Refusing to run: this writes fake measurements and is sandbox-only. Set NXEON_SANDBOX=1.");
25	  }
26	
27	  const account = await db.hostingAccount.findFirst({
28	    where: { user: { email: "customer@nxeon.local" } },
29	    orderBy: { createdAt: "asc" },
30	    include: { plan: true },
31	  });
32	  if (!account) throw new Error("No hosting account for customer@nxeon.local — order one first.");
33	
34	  const business = await db.hostingPlan.findUnique({ where: { slug: "business" } });
35	  if (!business) throw new Error("No 'business' hosting plan seeded.");
36	
37	  const quotaMB = business.diskGB * 1024;
38	  await db.hostingAccount.update({
39	    where: { id: account.id },
40	    data: {
41	      planId: business.id,
42	      status: "ACTIVE",
43	      maxSites: business.maxSites,
44	      maxDatabases: business.maxDatabases,
45	      diskQuotaMB: quotaMB,
46	      phpVersion: "8.3",
47	      sslActive: true,
48	      serveHttpOk: true,
49	      serveHttpsOk: true,
50	      healthNote: "HTTPS live — verified",
51	      healthCheckedAt: new Date(),
52	      diskUsedMB: 5_640,
53	      inodesUsed: 41_233,
54	      usageAt: new Date(),
55	      usageBreakdown: JSON.stringify({
56	        v: 1,
57	        dirs: [
58	          { path: "public_html", mb: 3120 },
59	          { path: "subdomains/shop", mb: 1180 },
60	          { path: "domains/nxeon-demo.example", mb: 890 },
61	          { path: "tmp", mb: 310 },
62	          { path: "logs", mb: 96 },
63	        ],
64	      }),
65	      sftpPasswordEnc: encryptSecret("sandbox-demo-sftp-pw"),
66	      provisionedAt: new Date(),
67	      expiresAt: new Date(Date.now() + 23 * 86_400_000),
68	    },
69	  });
70	
71	  // Two more websites, so the plan/website distinction is actually visible.
72	  const subFqdn = `shop.${account.primaryDomain}`;
73	  await db.hostingSubdomain.upsert({
74	    where: { fqdn: subFqdn },
75	    create: {
76	      accountId: account.id, label: "shop", fqdn: subFqdn,
77	      docroot: `/home/${account.username}/subdomains/shop/public_html`,
78	      sslActive: true, status: "ACTIVE",
79	    },
80	    update: { accountId: account.id, sslActive: true, status: "ACTIVE" },
81	  });
82	  await db.hostingAddonDomain.upsert({
83	    where: { domain: "nxeon-demo.example" },
84	    create: {
85	      accountId: account.id, domain: "nxeon-demo.example",
86	      docroot: `/home/${account.username}/domains/nxeon-demo.example/public_html`,
