import type { HostingPanelData, HostingSiteCard } from "@/components/customer/hosting/v2/types";

export const dynamic = "force-dynamic";

/** "/ month", "/ year", "/ 2 years" — the unit the renewal actually bills on. */
function termLabel(months: number): string {
  if (months === 1) return "/ month";
  if (months % 12 === 0) return months === 12 ? "/ year" : `/ ${months / 12} years`;
  return `/ ${months} mo`;
}

/**
 * One shared-hosting plan.
 *
 * Everything the panel renders is resolved HERE, once, and threaded down — the
 * old page handed a single `account` to a client tab shell that then re-fetched
 * the same counts from four different components on four different timers, which
 * is how its Overview came to disagree with its own Websites tab.
 *
 * The provisioning screen is the same `<Provisioning/>` the VPS and game flows
 * use, driven by the same real signals (account status plus
 * `hostingProvisioningStep`, which reads the worker's own per-command-group
 * label). What changed is WHEN it renders — see `showOverlay` below.
 */
export default async function HostingAccountPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ tab?: string; path?: string; site?: string; section?: string; purchase?: string }>;
}) {
  const [{ id }, { tab, path, site, section, purchase }] = await Promise.all([params, searchParams]);

  // getHostingAccount enforces owner-or-admin (throws) and returns null if missing.
  let account: Awaited<ReturnType<typeof getHostingAccount>> = null;
  try {
    account = await getHostingAccount(id);
  } catch {
    notFound();
  }
  if (!account) notFound();

  const transitional = account.status === "PENDING" || account.status === "PROVISIONING";

  const [raw, stepLabel, sites, thumbs, dbs, backups, appMenu, ftpUsers, storage, activity, upgradePlanCount] =
    await Promise.all([
      // A second, narrower lookup for the raw fields HostingAccountView doesn't
      // carry: whether an SFTP credential exists at all (never the secret itself —
      // that only ever leaves through the ownership-checked reveal action), and
      // the node's REAL ssh host/port, which is what a customer's SFTP client
      // must connect to and can differ from the public A-record target on NAT.
      db.hostingAccount.findUnique({
        where: { id: account.id },
        select: {
          sftpPasswordEnc: true,
          plan: { select: { bandwidthTB: true, mailboxes: true } },
          node: { select: { sshHost: true, sshPort: true, publicIp: true, hostnameFqdn: true } },
        },
      }),
      hostingProvisioningStep(account.id),
      listWebsites(account.id).catch(() => []),
      listSiteThumbs(account.id).catch(() => []),
      listHostingDatabases(account.id).catch(() => []),
      listHostingBackups(account.id).catch(() => []),
      listHostingAppMenu().catch(() => []),
      listFtpUsers(account.id).catch(() => []),
      hostingStorageBreakdown(account.id).catch(() => null),
      listHostingActivity(account.id, 24).catch(() => []),
      db.hostingPlan.count({
        where: { active: true, priceCents: { gt: account.planPriceCents } },
      }).catch(() => 0),
    ]);

  // The `siteKey` association lives on the row but isn't on HostingDbView — read
  // it alongside so the per-website Database section can name its database.
  const dbSiteKeys = await db.hostingDatabase
    .findMany({ where: { accountId: account.id }, select: { id: true, siteKey: true } })
    .catch(() => [] as { id: string; siteKey: string | null }[]);
  const siteKeyById = new Map(dbSiteKeys.map((d) => [d.id, d.siteKey]));

  // Real mailbox count for the plan's domain — only meaningful once the bundled
  // subscription exists. No subscription means there is nothing to count, which
  // is not the same as a count of zero, so it stays null and the tile says why.
  const emailSub = await db.emailSubscription
    .findFirst({
      where: { domainName: account.primaryDomain, status: { not: "CANCELLED" } },
      select: { id: true, _count: { select: { mailboxes: true } } },

