783	  selected,
784	  onToggleRow,
785	  onToggleAll,
786	  onEdit,
787	  onClone,
788	  onDelete,
789	  canInlineEdit,
790	  onInlineSave,
791	  truncated,
792	}: {
793	  columns: string[];
794	  rows: string[][];
795	  numericCols: Set<string>;
796	  sort: Sort;
797	  onSort: (col: string) => void;
798	  selected: Set<number>;
799	  onToggleRow: (i: number) => void;
800	  onToggleAll: () => void;
